      "number": 42,
      "arFull": "اَوْ نُرِیَنَّكَ الَّذِیْ وَعَدْنٰهُمْ فَاِنَّا عَلَیْهِمْ مُّقْتَدِرُوْنَ ۟",
      "ur": "یا جو کچھ ان سے وعده کیا ہے[1] وه تجھے دکھا دیں ہم ان پر بھی قدرت رکھتے ہیں.[2]",
