      "footnotesUr": "[1] یعنی تیری موت سے قبل ہی، یا مکے میں ہی تیرے رہتے ہوئے ان پر عذاب بھیج دیں۔\n[2] یعنی ہم جب چاہیں ان پر عذاب نازل کرسکتے ہیں، کیونکہ ہم ان پر قادر ہیں۔ چنانچہ آپ کی زندگی میں ہی بدر کی جنگ میں کافر عبرت ناک شکست، اور ذلت سے دوچار ہوئے۔",
