      "arFull": "اَلْاَخِلَّآءُ یَوْمَىِٕذٍ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ اِلَّا الْمُتَّقِیْنَ ۟ؕ۠",
      "ur": "اس دن (گہرے) دوست بھی ایک دوسرے کے دشمن بن جائیں گے سوائے پرہیزگاروں کے.[1]",
      "en": "Close friends, that Day, will be enemies to each other, except for the righteous",
      "footnotesUr": "[1] کیوں کہ کافروں کی دوستی، کفر وفسق کی بنیاد پر ہی ہوتی ہے اور یہی کفر وفسق ان کے عذاب کاباﻋﺚ ہوں گے، جس کی وجہ سے وہ ایک دوسرے کو مورد الزام ٹھہرائیں گے اور ایک دوسرے کے دشمن ہوجائیں گے۔ اس کے برعکس اہل ایمان و تقویٰ کی باہمی محبت، چونکہ دین اور رضائے الٰہی کی بنیاد پر ہوتی ہے اور یہی دین وایمان خیروثواب کا باعث ہے۔ ان سے ان کی دوستی میں کوئی انقطاع نہیں ہوگا۔ وہ اسی طرح برقرار رہے گی جس طرح دنیا میں تھی۔",
