      "arTajweed": "لَا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُ<span class=\"tj-qalaqah\">بْ</span>لِسُ<span class=\"tj-madda-permissible\">و</span>نَ"
